INSERT INTO inquiry_templates (id, clinic_id, category, title, content, is_active, sort_order, created_at, updated_at) VALUES
    (1,  3, 'chief_complaint',   '食欲不振（急性）',       'いつ頃から食欲が落ちましたか？完全に食べないのか、減っているだけか確認してください。',                     true, 1,  '2026-04-14 11:07:04.762212+00', '2026-04-14 11:07:04.762212+00'),
    (2,  3, 'chief_complaint',   '嘔吐（回数・内容物）',   '嘔吐の回数、内容物（食物・胆汁・血液など）、嘔吐のタイミング（食後すぐ・空腹時）を確認してください。',     true, 2,  '2026-04-14 11:07:04.762212+00', '2026-04-14 11:07:04.762212+00'),
    (3,  3, 'chief_complaint',   '下痢（性状・頻度）',     '便の性状（軟便・水様便・血便・粘液便）、排便頻度、いつから続いているか確認してください。',                 true, 3,  '2026-04-14 11:07:04.762212+00', '2026-04-14 11:07:04.762212+00'),
    (4,  3, 'chief_complaint',   '皮膚の痒み・発赤',       '痒がる部位、発症時期、季節性の有無、ノミ・ダニ予防の状況を確認してください。',                           true, 4,  '2026-04-14 11:07:04.762212+00', '2026-04-14 11:07:04.762212+00'),
    (5,  3, 'chief_complaint',   '排尿異常',               '排尿回数の変化、尿の色・量、排尿時の痛みの有無、血尿の有無を確認してください。',                         true, 5,  '2026-04-14 11:07:04.762212+00', '2026-04-14 11:07:04.762212+00'),
    (6,  3, 'history',           '既往歴確認（手術歴）',   '過去の手術歴（去勢・避妊含む）、入院歴、重大な疾患の既往を確認してください。',                           true, 6,  '2026-04-14 11:07:04.762212+00', '2026-04-14 11:07:04.762212+00'),
    (7,  3, 'history',           '予防接種歴確認',         '最終ワクチン接種日、狂犬病予防接種の有無、フィラリア予防の状況を確認してください。',                     true, 7,  '2026-04-14 11:07:04.762212+00', '2026-04-14 11:07:04.762212+00'),
    (8,  3, 'current_medications', '現在の投薬状況',       '現在服用中の薬剤名、用量、投与期間、処方元の病院を確認してください。',                                 true, 8,  '2026-04-14 11:07:04.762212+00', '2026-04-14 11:07:04.762212+00'),
    (9,  3, 'current_medications', 'サプリメント・フード', '現在与えているサプリメント、療法食、おやつの種類を確認してください。',                                 true, 9,  '2026-04-14 11:07:04.762212+00', '2026-04-14 11:07:04.762212+00'),
    (10, 3, 'notes',             '生活環境確認',           '室内飼い/外飼い、同居動物の有無、散歩の頻度・時間を確認してください。',                                 true, 10, '2026-04-14 11:07:04.762212+00', '2026-04-14 11:07:04.762212+00'),
    (11, 4, 'chief_complaint',   '食欲不振',               'いつ頃から食欲が低下しましたか？完全絶食か減少かを確認してください。',                                   true, 1,  '2026-04-14 11:07:04.762212+00', '2026-04-14 11:07:04.762212+00'),
    (12, 4, 'chief_complaint',   '嘔吐',                   '嘔吐の回数・内容物・タイミングを確認してください。',                                                   true, 2,  '2026-04-14 11:07:04.762212+00', '2026-04-14 11:07:04.762212+00'),
    (13, 4, 'chief_complaint',   '下痢',                   '便の性状・排便頻度・持続期間を確認してください。',                                                     true, 3,  '2026-04-14 11:07:04.762212+00', '2026-04-14 11:07:04.762212+00'),
    (14, 4, 'history',           '既往歴・手術歴',         '過去の手術歴・入院歴・重大な疾患の既往を確認してください。',                                           true, 4,  '2026-04-14 11:07:04.762212+00', '2026-04-14 11:07:04.762212+00'),
    (15, 4, 'history',           '予防接種歴',             '最終ワクチン接種日・狂犬病予防・フィラリア予防の状況を確認してください。',                               true, 5,  '2026-04-14 11:07:04.762212+00', '2026-04-14 11:07:04.762212+00'),
    (16, 4, 'current_medications', '投薬状況',             '現在服用中の薬剤名・用量・処方元を確認してください。',                                                 true, 6,  '2026-04-14 11:07:04.762212+00', '2026-04-14 11:07:04.762212+00'),
    (17, 4, 'notes',             '生活環境',               '室内飼い/外飼い・同居動物・散歩頻度を確認してください。',                                               true, 7,  '2026-04-14 11:07:04.762212+00', '2026-04-14 11:07:04.762212+00'),
    (18, 5, 'chief_complaint',   '食欲低下',               'いつから食べなくなったか、食事内容の変化はあるか確認してください。',                                   true, 1,  '2026-04-14 11:07:04.762212+00', '2026-04-14 11:07:04.762212+00'),
    (19, 5, 'chief_complaint',   '嘔吐・吐出',             '嘔吐の頻度・内容物・食事との関連を確認してください。',                                                 true, 2,  '2026-04-14 11:07:04.762212+00', '2026-04-14 11:07:04.762212+00'),
    (20, 5, 'chief_complaint',   '消化器症状（下痢）',     '便の状態・頻度・血便の有無を確認してください。',                                                       true, 3,  '2026-04-14 11:07:04.762212+00', '2026-04-14 11:07:04.762212+00'),
    (21, 5, 'history',           '既往歴確認',             '手術歴・入院歴・アレルギー歴を確認してください。',                                                     true, 4,  '2026-04-14 11:07:04.762212+00', '2026-04-14 11:07:04.762212+00'),
